inputs = ['buvh', 'fxv', 'vk', 'kvkkzy', 'ju']
outputs = ['buvh', 'fxv', 'vk', 'kvkkzzeazea', 'ju']

# Let's check what happens if we try different replacements
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        print(f"  Difference: {len(inp)} -> {len(outp)} chars")

# Special focus on the 4th pair
inp4, outp4 = inputs[3], outputs[3]
print(f"\nDetailed analysis of pair 4:")
print(f"Input:  '{inp4}'")
print(f"Output: '{outp4}'")
print(f"Input length: {len(inp4)}, Output length: {len(outp4)}")

# Let's see what characters differ
for i in range(max(len(inp4), len(outp4))):
    if i < len(inp4) and i < len(outp4):
        if inp4[i] != outp4[i]:
            print(f"Position {i}: '{inp4[i]}' -> '{outp4[i]}'")
    elif i < len(inp4):
        print(f"Position {i}: '{inp4[i]}' (extra in input)")
    elif i < len(outp4):
        print(f"Position {i}: '{outp4[i]}' (extra in output)")

